cd /tmp && cat > b32.js <<'EOF'
const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
function polymod(values){
  const GEN=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];
  let chk=1;
  for(const v of values){ const b=chk>>25; chk=((chk&0x1ffffff)<<5)^v;
    for(let i=0;i<5;i++){ if((b>>i)&1) chk^=GEN[i]; } }
  return chk;
}
function hrpExpand(hrp){ const a=[],b=[];
  for(const c of hrp){ a.push(c.charCodeAt(0)>>5); b.push(c.charCodeAt(0)&31); }
  return a.concat([0],b);
}
function createChecksum(hrp,data){
  const values=hrpExpand(hrp).concat(data).concat([0,0,0,0,0,0]);
  const pm=polymod(values)^1; const out=[];
  for(let i=0;i<6;i++) out.push((pm>>(5*(5-i)))&31);
  return out;
}
function bech32Encode(hrp,data){
  return hrp+"1"+createChecksum(hrp,data).reduce((s,d)=>s+CHARSET[d],data.reduce((s,d)=>s+CHARSET[d],""));
}
function convertbits(data,from,to,pad=true){
  let acc=0,bits=0; const ret=[]; const maxv=(1<<to)-1;
  for(const v of data){ if(v<0||(v>>from)) return null; acc=(acc<<from)|v; bits+=from;
    while(bits>=to){ bits-=to; ret.push((acc>>bits)&maxv); } }
  if(pad){ if(bits) ret.push((acc<<(to-bits))&maxv); }
  else if(bits>=from||((acc<<(to-bits))&maxv)) return null;
  return ret;
}
function segwitEncode(hrp,ver,prog){
  const c=convertbits(prog,8,5,true);
  return bech32Encode(hrp,[ver].concat(c));
}
module.exports={CHARSET,bech32Encode,createChecksum,convertbits,segwitEncode,polymod,hrpExpand};
