const B = require("/tmp/b32.js");
const P = [];
const add = (l, a, b) => P.push(l + "|" + Buffer.from(a, "binary").toString("base64") + "|" + Buffer.from(b, "binary").toString("base64"));
const good = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";

// --- very long strings ---
for (const n of [50, 89, 90, 91, 92, 100, 200, 1000, 10000, 65536]) {
  add("longq_" + n, "bc", "q".repeat(n));
  add("long1_" + n, "bc", "1".repeat(n));
  add("longbc1_" + n, "bc", "bc1" + "q".repeat(n));
  add("longhrp_" + n, "q".repeat(n), "q".repeat(n) + "1qqqqqq");
}
// separators only
for (let n = 0; n <= 12; n++) { add("onlyones_" + n, "bc", "1".repeat(n)); add("onlyones_emptyhrp_" + n, "", "1".repeat(n)); }
// all q
for (let n = 0; n <= 12; n++) add("allq_" + n, "bc", "q".repeat(n));
// hrp mismatch variants
const hrps = ["b", "bc", "bcc", "c", "BC", "Bc", "bC", "bc ", " bc", "bc1", "1bc", "tb", "bc\n", "bc\t", "é", "bcé", "ébc", "bcx", "bc.", "bc-", "bc_", good, "q".repeat(200), "q".repeat(10000), "", "0", "-", "--", "-a", "-b", "--a", "�", "bc�", "ÿ", "中文", "😀"];
for (const a of hrps) add("hrpvar[" + JSON.stringify(a).slice(0, 30) + "]", a, good);
process.stdout.write(P.join("\n") + "\n");

const { spawnSync } = require("child_process");
const EXE = "/workspace/dataset/test5_executable";
const results = [];
let n = 0;

function probe(label, argv) {
  n++;
  let r;
  try {
    r = spawnSync(EXE, argv, { encoding: "utf8", maxBuffer: 1 << 28 });
  } catch (e) {
    return { label, argv, rc: "SPAWN_THROW", stdout: "", stderr: String(e.message), clean: false };
  }
  if (r.error) return { label, argv, rc: "SPAWN_ERR", stdout: "", stderr: String(r.error.message), clean: false };
  const out = r.stdout === null ? "<null>" : r.stdout;
  const err = r.stderr === null ? "<null>" : r.stderr;
  const rc = r.status;
  const sig = r.signal;
  const o = out.replace(/\n$/, "");
  let clean = false, kind = "OTHER";
  if (rc === 0 && err === "" && sig === null) {
    if (o === "(None, None)") { clean = true; kind = "NONE"; }
    else if (/^\(\d+, \[(\d+(, \d+)*)?\]\)$/.test(o)) { clean = true; kind = "OK"; }
  }
  const rec = { label, argv, rc, sig, stdout: out, stderr: err, clean, kind };
  results.push(rec);
  return rec;
}
module.exports = { probe, results, count: () => n };

const H = require("/tmp/harness.js");
const B = require("/tmp/b32.js");
const good = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";
const anomalies = [];
const successes = [];

function P(label, a, b) {
  let r;
  try { r = H.probe(label, ["--a=" + a, "--b=" + b]); }
  catch (e) { anomalies.push({ label, note: "node spawn refused: " + e.message, a, b }); return; }
  if (!r) return;
  if (!r.clean) anomalies.push({ label, a: JSON.stringify(a).slice(0, 120), b: JSON.stringify(b).slice(0, 160), rc: r.rc, sig: r.sig, stdout: r.stdout.slice(0, 400), stderr: r.stderr.slice(0, 800) });
  else if (r.kind === "OK") successes.push({ label, a: JSON.stringify(a).slice(0, 80), b: JSON.stringify(b).slice(0, 120), out: r.stdout.trim().slice(0, 200) });
}
module.exports = { P, anomalies, successes, H, B, good };

const { P, anomalies, successes, H, B, good } = require("/tmp/p.js");

// ---- 1. very long strings ----
for (const n of [50, 89, 90, 91, 92, 100, 200, 1000, 10000, 100000]) {
  P("longq_" + n, "bc", "q".repeat(n));
  P("long1_" + n, "bc", "1".repeat(n));
  P("longbc1q_" + n, "bc", "bc1" + "q".repeat(n));
  P("longhrpboth_" + n, "q".repeat(n), "q".repeat(n) + "1qqqqqq");
  P("longA_" + n, "q".repeat(n), good);
  P("longmix_" + n, "bc", "bc1" + "qpzry9x8gf2tvdw0s3jn54khce6mua7l".repeat(Math.ceil(n / 32)).slice(0, n));
}
// ---- 2. separators only / all-q ----
for (let n = 0; n <= 14; n++) {
  P("ones_" + n, "bc", "1".repeat(n));
  P("ones_emptyA_" + n, "", "1".repeat(n));
  P("allq_" + n, "bc", "q".repeat(n));
  P("bc1ones_" + n, "bc", "bc" + "1".repeat(n));
  P("q1_" + n, "q", "q" + "1".repeat(n));
}
// ---- 3. HRP variants in --a ----
const hrps = ["b", "bc", "bcc", "c", "BC", "Bc", "bC", "bc ", " bc", "bc1", "1bc", "tb", "bcx", "bc.", "bc-", "bc_", good, "", "0", "1", "-", "--", "-a", "-b", "--a", " ",
  "bc\n", "bc\t", "bc\r", "\nbc", "bc\x0b", "bc\x7f", "bc\x1b", "é", "bcé", "ébc", "ÿ", "中文", "😀", "ａｂ", " bc", "bc​",
  "q".repeat(83), "q".repeat(84), "q".repeat(200), "q".repeat(10000), "BC1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4"];
for (const a of hrps) P("Avar[" + JSON.stringify(a).slice(0, 26) + "]", a, good);

// ---- 4. addresses with valid checksum but tiny data parts ----
const CH = B.CHARSET;
for (const hrp of ["bc", "a", "q", "1", "x1y", "tb"]) {
  for (let k = 0; k <= 4; k++) {
    const data = [];
    for (let i = 0; i < k; i++) data.push(i % 32);
    const addr = B.bech32Encode(hrp, data);
    P("emptypayload_hrp=" + hrp + "_ndata=" + k, hrp, addr);
    P("emptypayload_mismatchA_hrp=" + hrp + "_ndata=" + k, "zz", addr);
  }
}
// every single-value data part 0..31 for hrp bc  (version-only, no program)
for (let v = 0; v < 32; v++) P("veronly_v" + v, "bc", B.bech32Encode("bc", [v]));
// two data values
for (let v = 0; v < 32; v += 3) for (const w of [0, 1, 15, 16, 31]) P("twodata_" + v + "_" + w, "bc", B.bech32Encode("bc", [v, w]));

console.log("PROBES:", H.count());
console.log("ANOMALIES:", JSON.stringify(anomalies, null, 1));
console.log("N_SUCCESS:", successes.length);
console.log(JSON.stringify(successes, null, 1).slice(0, 4000));

const { P, anomalies, successes, H, B, good } = require("/tmp/p.js");
const raw = [];
function R(label, argv) { const r = H.probe(label, argv); raw.push([label, argv, r.rc, JSON.stringify(r.stdout), JSON.stringify(r.stderr)]); return r; }

// explicit look at tiny valid-checksum payloads
for (let k = 0; k <= 3; k++) {
  const data = []; for (let i = 0; i < k; i++) data.push(i);
  const addr = B.bech32Encode("bc", data);
  R("EXPLICIT ndata=" + k + " addr=" + addr, ["--a=bc", "--b=" + addr]);
}
// data=[0,0] and [0,16] etc
for (const d of [[0], [0, 0], [0, 1], [1], [16], [17], [31], [0, 0, 0], [1, 0, 0], [1, 0, 1]]) {
  const addr = B.bech32Encode("bc", d);
  R("EXPLICIT data=" + JSON.stringify(d) + " addr=" + addr, ["--a=bc", "--b=" + addr]);
}
for (const r of raw) console.log(r[0], "\n   rc=" + r[2], "out=" + r[3], "err=" + r[4]);

const { P, anomalies, successes, H, B, good } = require("/tmp/p.js");
const notes = [];
function shown(label, argv) {
  const r = H.probe(label, argv);
  notes.push([label, r.rc, r.stdout.replace(/\n$/, "").slice(0, 220), r.stderr.replace(/\n+$/, "").slice(0, 300)]);
  return r;
}

// ===== witness version x program length matrix =====
function padHrp(len) { return "x".repeat(len); }
for (const ver of [0, 1, 2, 15, 16, 17, 18, 31]) {
  for (const plen of [0, 1, 2, 3, 19, 20, 21, 31, 32, 33, 39, 40, 41, 50]) {
    const prog = []; for (let i = 0; i < plen; i++) prog.push((i * 7 + 3) & 0xff);
    let addr;
    try { addr = B.segwitEncode("bc", ver, prog); } catch (e) { continue; }
    if (addr.length > 90) { shown("TOOLONG ver=" + ver + " plen=" + plen + " len=" + addr.length, ["--a=bc", "--b=" + addr]); continue; }
    shown("ver=" + ver + " plen=" + plen + " addrlen=" + addr.length, ["--a=bc", "--b=" + addr]);
  }
}

// ===== exactly 90 / 91 / 89 char checksum-valid addresses =====
for (const total of [88, 89, 90, 91, 92, 95]) {
  // ver 0, 32-byte prog -> 52 data groups (1+52=53) + 6 chk = 59; hrp = total-1-59
  const prog32 = []; for (let i = 0; i < 32; i++) prog32.push(i * 3 & 0xff);
  let hlen = total - 1 - (1 + B.convertbits(prog32, 8, 5, true).length) - 6;
  if (hlen >= 1) {
    const hrp = "x".repeat(hlen);
    const addr = B.segwitEncode(hrp, 0, prog32);
    shown("TOTALLEN=" + addr.length + " v0/32 hrplen=" + hlen, ["--a=" + hrp, "--b=" + addr]);
  }
  // ver 1, 40-byte prog
  const prog40 = []; for (let i = 0; i < 40; i++) prog40.push(i & 0xff);
  let hlen2 = total - 1 - (1 + B.convertbits(prog40, 8, 5, true).length) - 6;
  if (hlen2 >= 1) {
    const hrp = "y".repeat(hlen2);
    const addr = B.segwitEncode(hrp, 1, prog40);
    shown("TOTALLEN=" + addr.length + " v1/40 hrplen=" + hlen2, ["--a=" + hrp, "--b=" + addr]);
  }
}

// ===== argparse quirks =====
const A = [
  ["sep_space", ["--a", "bc", "--b", good]],
  ["leadingdash_b", ["--a", "bc", "--b", "-bc1qqqqqq"]],
  ["leadingdash_b_eq", ["--a=bc", "--b=-bc1qqqqqq"]],
  ["leadingdash_a", ["--a", "-bc", "--b", good]],
  ["dashdash", ["--a", "bc", "--", "--b", good]],
  ["dashdash2", ["--", "--a=bc", "--b=" + good]],
  ["abbrev_-a", ["-a", "bc", "-b", good]],
  ["dup_a", ["--a=bc", "--a=tb", "--b=" + good]],
  ["dup_b", ["--a=bc", "--b=nope", "--b=" + good]],
  ["missing_val_a", ["--a"]],
  ["missing_val_b", ["--a=bc", "--b"]],
  ["extra_positional", ["--a=bc", "--b=" + good, "extra"]],
  ["unknown_opt", ["--a=bc", "--b=" + good, "--c=1"]],
  ["only_a", ["--a=bc"]],
  ["only_b", ["--b=" + good]],
  ["help_plus", ["-h", "--a=bc", "--b=" + good]],
  ["empty_eq", ["--a=", "--b="]],
  ["a_equals_only", ["--a==bc", "--b=" + good]],
  ["b_with_equals_in_val", ["--a=bc", "--b==" + good]],
  ["reversed", ["--b=" + good, "--a=bc"]],
  ["long_prefix_aa", ["--aa=bc", "--b=" + good]],
];
for (const [l, argv] of A) shown("ARGPARSE " + l, argv);

for (const n of notes) console.log(n[0] + "\n   rc=" + n[1] + " out=" + JSON.stringify(n[2]) + (n[3] ? " err=" + JSON.stringify(n[3]) : ""));

const { P, anomalies, successes, H, B, good } = require("/tmp/p.js");
const out = [];
function S(label, a, b) {
  const r = H.probe(label, ["--a=" + a, "--b=" + b]);
  out.push(label + " | addrlen=" + b.length + " | rc=" + r.rc + " | " + JSON.stringify(r.stdout.replace(/\n$/, "").slice(0, 120)) + (r.stderr ? " ERR=" + JSON.stringify(r.stderr.slice(0, 200)) : ""));
}
const prog32 = []; for (let i = 0; i < 32; i++) prog32.push(i * 3 & 0xff);
// sweep hrp length -> address length across the 90 boundary and far beyond
for (const hlen of [1, 2, 20, 28, 29, 30, 31, 32, 40, 60, 100, 141, 200, 500, 1000, 5000]) {
  const hrp = "x".repeat(hlen);
  const addr = B.segwitEncode(hrp, 0, prog32);
  S("v0/32 hrplen=" + hlen, hrp, addr);
}
// also grow the *data* part beyond 90 total with a legal 40-byte program
const prog40 = []; for (let i = 0; i < 40; i++) prog40.push(i & 0xff);
for (const hlen of [17, 18, 19, 20, 50, 300]) {
  const hrp = "y".repeat(hlen);
  S("v1/40 hrplen=" + hlen, hrp, B.segwitEncode(hrp, 1, prog40));
}
// uppercase versions of an over-90 address
{
  const hrp = "x".repeat(31);
  const addr = B.segwitEncode(hrp, 0, prog32);
  S("over90 UPPER addr", hrp, addr.toUpperCase());
  S("over90 UPPER addr, upper A", hrp.toUpperCase(), addr.toUpperCase());
}
console.log(out.join("\n"));

const { H, B } = require("/tmp/p.js");
const rows = [];
function S(tag, a, b) {
  const r = H.probe(tag, ["--a=" + a, "--b=" + b]);
  const ok = /^\(\d+,/.test(r.stdout);
  rows.push({ tag, hrplen: a.length, addrlen: b.length, rc: r.rc, ok, out: r.stdout.replace(/\n$/, "").slice(0, 40), err: r.stderr.slice(0, 200) });
  return ok;
}
