const prog2 = [3, 10];
let flip = [];
for (let hlen = 1; hlen <= 200; hlen++) {
  const hrp = "x".repeat(hlen);
  const addr = B.segwitEncode(hrp, 1, prog2);
  const ok = S("shortdata hrplen=" + hlen, hrp, addr);
  flip.push([hlen, addr.length, ok]);
}
// report only transitions
let prev = null;
const trans = [];
for (const [h, al, ok] of flip) { if (prev === null || ok !== prev) trans.push({ hrplen: h, addrlen: al, ok }); prev = ok; }
console.log("TRANSITIONS (short data part, 11 chars):", JSON.stringify(trans));
console.log("failing rows sample:", JSON.stringify(rows.filter(r => !r.ok).slice(0, 3)));
console.log("last ok:", JSON.stringify(rows.filter(r => r.ok).slice(-2)));

const { H, B } = require("/tmp/p.js");
const rows = [];
function S(tag, a, b) {
  const r = H.probe(tag, ["--a=" + a, "--b=" + b]);
  rows.push(tag + " [alen=" + a.length + ",blen=" + b.length + "] rc=" + r.rc + " out=" + JSON.stringify(r.stdout.replace(/\n$/, "").slice(0, 90)) + (r.stderr ? " ERR=" + JSON.stringify(r.stderr.slice(0, 200)) : "") + (r.sig ? " SIG=" + r.sig : ""));
  return r;
}
const prog40 = []; for (let i = 0; i < 40; i++) prog40.push(i & 0xff);
const prog2 = [3, 10];

// ---- absolute max length success: hrp 83, v1, 40-byte prog ----
for (const hlen of [82, 83, 84]) {
  const hrp = "z".repeat(hlen);
  S("MAXLEN hrplen=" + hlen, hrp, B.segwitEncode(hrp, 1, prog40));
}
