for (const hlen of [1, 83, 84]) {
  const hrp = "w".repeat(hlen);
  S("EMPTYPAYLOAD hrplen=" + hlen, hrp, B.bech32Encode(hrp, []));
}
// ---- HRP containing '1' ----
for (const hrp of ["x1x", "1x", "x1", "11", "a1b1c", "1", "x11", "bc1", "a".repeat(40) + "1" + "a".repeat(42)]) {
  const addr = B.segwitEncode(hrp, 1, prog2);
  S("HRP_WITH_1 hrp=" + JSON.stringify(hrp).slice(0, 20), hrp, addr);
  // also try with --a set to the part after the last 1
  const li = hrp.lastIndexOf("1");
  if (li >= 0) S("HRP_WITH_1 wrongA hrp=" + JSON.stringify(hrp).slice(0, 20), hrp.slice(li + 1), addr);
}
