const g = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";
S("append1", "bc", g + "1");
S("prepend1", "bc", "1" + g);
S("append1_A=full", g, g + "1");
S("insert1", "bc", g.slice(0, 10) + "1" + g.slice(10));
S("doublesep", "bc", "bc11qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4");

// ---- invalid charset chars in data part ----
for (const ch of ["b", "i", "o", "1", "B", "I", "O", "-", " ", "!", "~", "\x7f", "\x20", "\x21", "\x7e"]) {
  S("badchar[" + JSON.stringify(ch) + "]", "bc", g.slice(0, 20) + ch + g.slice(21));
}
// ---- control chars & whitespace in --b ----
for (const [n, ch] of [["nl", "\n"], ["cr", "\r"], ["tab", "\t"], ["vt", "\x0b"], ["ff", "\x0c"], ["esc", "\x1b"], ["bel", "\x07"], ["sp", " "], ["del", "\x7f"], ["so", "\x0e"]]) {
