S("kelvin_addr", "bc", "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7Kv8f3t4");
S("turkishI_addr", "bc", "BCİ1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4");
