  rows.push(tag + " [alen=" + a.length + ",blen=" + b.length + "] rc=" + r.rc + " out=" + JSON.stringify(r.stdout.replace(/\n$/, "").slice(0, 80)) + (r.stderr ? " ERR=" + JSON.stringify(r.stderr.slice(0, 200)) : ""));
  return r;
}
const prog20 = []; for (let i = 0; i < 20; i++) prog20.push(i);
const prog32 = []; for (let i = 0; i < 32; i++) prog32.push(i * 3 & 0xff);
const prog40 = []; for (let i = 0; i < 40; i++) prog40.push(i);

// ---- exact hrp cut for several data-part sizes ----
for (const [nm, ver, prog] of [["v0/20", 0, prog20], ["v0/32", 0, prog32], ["v1/40", 1, prog40], ["v1/2", 1, [3, 10]]]) {
  for (const hlen of [82, 83, 84, 85]) {
    const hrp = "k".repeat(hlen);
    S("HRPCUT " + nm + " hrplen=" + hlen, hrp, B.segwitEncode(hrp, ver, prog));
  }
}
// ---- padding bits: program of 2 bytes needs 4 groups w/ 4 zero pad bits ----
{
  const base = B.convertbits([3, 10], 8, 5, true); // 4 groups
  for (let pad = 0; pad < 16; pad++) {
    const d = base.slice();
    d[3] = (d[3] & ~0x0f) | pad;      // low 4 bits are the pad bits
    const addr = B.bech32Encode("bc", [1].concat(d));
    S("PAD prog2 padbits=" + pad + " groups=" + JSON.stringify(d), "bc", addr);
  }
}
// ---- extra trailing group (bits >= frombits) ----
for (const extra of [0, 1, 2]) {
  const d = [0].concat(B.convertbits(prog20, 8, 5, true));
  for (let i = 0; i < extra; i++) d.push(0);
  S("EXTRAGROUP v0/20 +" + extra + " ndata=" + d.length, "bc", B.bech32Encode("bc", d));
}
// ---- huge valid-checksum data parts ----
for (const n of [70, 71, 72, 100, 500, 2000, 20000]) {
  const d = []; for (let i = 0; i < n; i++) d.push(i % 32);
  const addr = B.bech32Encode("bc", d);
  S("HUGEDATA n=" + n, "bc", addr);
}
// ---- hrp 83 + 41-byte program ----
{
  const p41 = []; for (let i = 0; i < 41; i++) p41.push(i);
  const hrp = "k".repeat(83);
  S("HRP83 v1/41", hrp, B.segwitEncode(hrp, 1, p41));
}
// ---- hrp = "1" family, print the addresses ----
for (const hrp of ["1", "11", "111"]) {
  const addr = B.segwitEncode(hrp, 1, [3, 10]);
  S("SEP_HRP hrp=" + JSON.stringify(hrp) + " addr=" + addr, hrp, addr);
}
console.log(rows.join("\n"));

const { H, B } = require("/tmp/p.js");
const rows = [];
function S(tag, a, b) {
  const r = H.probe(tag, ["--a=" + a, "--b=" + b]);
  rows.push({ tag, rc: r.rc, out: r.stdout.replace(/\n$/, ""), err: r.stderr, sig: r.sig, ok: /^\(\d+,/.test(r.stdout) });
  return r;
}
// ---- every byte 1..255 as a 1-char HRP (checksum computed over that char) ----
const accepted = [], rejected = [], weird = [];
for (let c = 1; c <= 255; c++) {
  const hrp = String.fromCharCode(c);
  let addr;
  try { addr = B.segwitEncode(hrp, 1, [3, 10]); } catch (e) { continue; }
  const r = S("BYTE_HRP " + c, hrp, addr);
  if (/^\(\d+,/.test(r.stdout)) accepted.push(c);
  else if (r.stdout.replace(/\n$/, "") === "(None, None)") rejected.push(c);
  else weird.push([c, r.rc, r.stdout, r.stderr]);
}
console.log("1-char-HRP ACCEPTED byte values:", JSON.stringify(accepted));
console.log("  as chars:", JSON.stringify(accepted.map(c => String.fromCharCode(c)).join("")));
console.log("  min/max:", Math.min(...accepted), Math.max(...accepted), "count:", accepted.length);
console.log("REJECTED count:", rejected.length, "WEIRD:", JSON.stringify(weird));

// ---- case rules: flip one char at a time in a valid address ----
const g = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";
const caseRows = [];
for (const i of [0, 1, 2, 3, 10, 20, 41]) {
  const s = g.slice(0, i) + g[i].toUpperCase() + g.slice(i + 1);
  if (s === g) { caseRows.push("idx " + i + ": no cased char"); continue; }
  const r = S("CASEFLIP " + i, "bc", s);
  caseRows.push("idx " + i + " -> " + r.stdout.replace(/\n$/, "").slice(0, 30));
}
// all-upper except one lower
{
  const U = g.toUpperCase();
  const s = U.slice(0, 5) + U[5].toLowerCase() + U.slice(6);
  caseRows.push("allupper-one-lower(" + s.slice(0, 8) + "..) -> " + S("CASE mixed2", "bc", s).stdout.replace(/\n$/, "").slice(0, 30));
  caseRows.push("allupper -> " + S("CASE allupper", "bc", U).stdout.replace(/\n$/, "").slice(0, 30));
  caseRows.push("allupper A=upper -> " + S("CASE allupperA", "BC", U).stdout.replace(/\n$/, "").slice(0, 30));
}
// hrp with non-letter chars, mixed with digits (no cased chars at all)
{
  const hrp = "!@#$%";
  caseRows.push("hrp=!@#$% -> " + S("HRP punct", hrp, B.segwitEncode(hrp, 1, [3, 10])).stdout.replace(/\n$/, "").slice(0, 30) + " addr=" + B.segwitEncode(hrp, 1, [3, 10]));
  const hrp2 = "0123456789";
  caseRows.push("hrp=digits -> " + S("HRP digits", hrp2, B.segwitEncode(hrp2, 1, [3, 10])).stdout.replace(/\n$/, "").slice(0, 30));
  const hrp3 = "~~~";
  caseRows.push("hrp=~~~ -> " + S("HRP tilde", hrp3, B.segwitEncode(hrp3, 1, [3, 10])).stdout.replace(/\n$/, "").slice(0, 30));
  const hrp4 = '"\\\'`';
  caseRows.push("hrp=quotes -> " + S("HRP quotes", hrp4, B.segwitEncode(hrp4, 1, [3, 10])).stdout.replace(/\n$/, "").slice(0, 30));
}
console.log(caseRows.join("\n"));
console.log("anom:", JSON.stringify(rows.filter(r => r.rc !== 0 || r.err || r.sig).slice(0, 10)));

const { H, B } = require("/tmp/p.js");
const out = [];
function S(tag, a, b) {
  const r = H.probe(tag, ["--a=" + a, "--b=" + b]);
  out.push(tag + " rc=" + r.rc + " out=" + JSON.stringify(r.stdout.replace(/\n$/, "").slice(0, 70)) + (r.stderr ? " ERR=" + JSON.stringify(r.stderr.slice(0, 300)) : "") + (r.sig ? " SIG=" + r.sig : ""));
  return r;
}
const g = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";
const U = g.toUpperCase();
// ---- definitive mixed case: lower exactly one CASED char of the uppercase form ----
for (let i = 0; i < U.length; i++) {
  if (U[i].toLowerCase() === U[i]) continue;      // not a cased char
  const s = U.slice(0, i) + U[i].toLowerCase() + U.slice(i + 1);
  S("MIXED lower@" + i + "(" + U[i] + ")", "bc", s);
  break;
}
for (let i = 0; i < g.length; i++) {
  if (g[i].toUpperCase() === g[i]) continue;
  const s = g.slice(0, i) + g[i].toUpperCase() + g.slice(i + 1);
  S("MIXED upper@" + i + "(" + g[i] + ")", "bc", s);
  break;
}
// ---- uppercase-HRP addresses, fully uppercased ----
for (const hrp of ["A", "BC", "Z", "aB", "A1B"]) {
  const addr = B.segwitEncode(hrp.toLowerCase(), 1, [3, 10]).toUpperCase();
  S("UPPERADDR hrp=" + hrp + " addr=" + addr + " A=" + hrp.toLowerCase(), hrp.toLowerCase(), addr);
  S("UPPERADDR hrp=" + hrp + " A=" + hrp, hrp, addr);
  S("UPPERADDR hrp=" + hrp + " A=" + hrp.toUpperCase(), hrp.toUpperCase(), addr);
}
// ---- bech32m rejection (constant 0x2bc830a3) ----
function polymodM(values) { const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]; let chk = 1; for (const v of values) { const b = chk >> 25; chk = ((chk & 0x1ffffff) << 5) ^ v; for (let i = 0; i < 5; i++) if ((b >> i) & 1) chk ^= GEN[i]; } return chk; }
function enc32m(hrp, data) {
  const vals = B.hrpExpand(hrp).concat(data).concat([0, 0, 0, 0, 0, 0]);
  const pm = polymodM(vals) ^ 0x2bc830a3; const o = [];
  for (let i = 0; i < 6; i++) o.push((pm >>> (5 * (5 - i))) & 31);
  return hrp + "1" + data.concat(o).map(d => B.CHARSET[d]).join("");
}
for (const [ver, plen] of [[0, 20], [0, 32], [1, 32], [1, 2], [16, 40]]) {
  const prog = []; for (let i = 0; i < plen; i++) prog.push(i);
  const data = [ver].concat(B.convertbits(prog, 8, 5, true));
  S("BECH32M ver=" + ver + " plen=" + plen, "bc", enc32m("bc", data));
}
S("REAL taproot bech32m", "bc", "bc1pmfr3p9j00pfxjh0zmgp99y8zftmd3s5pmedqhyptwy6lm87hf5sspknck9");
S("REAL taproot bech32m upper", "bc", "bc1pmfr3p9j00pfxjh0zmgp99y8zftmd3s5pmedqhyptwy6lm87hf5sspknck9".toUpperCase());
// BIP-173 official invalid vectors
const bad = [
  ["\x201nwldj5", ""], ["\x7f1axkwrx", ""], ["\x801eym55h", ""],
  ["pzry9x0s0luk", ""], ["1pzry9x0s0luk", ""], ["x1b4n0q5v", ""], ["li1dgmt3", ""],
  ["de1lg7wt\xff", ""], ["A1G7SGD8", ""], ["10a06t8", ""], ["1qzzfhee", ""],
  ["an84characterslonghumanreadablepartthatcontainsthenumber1andtheexcludedcharactersbio1569pvx", ""],
  ["bc1rw5uspcuh", ""], ["bc10w508d6qejxtdg4y5r3zarvaryvqyzf3du3", ""],
  ["BC1QR508D6QEJXTDG4Y5R3ZARVARYVQYZF3DU", ""], ["bc1zw508d6qejxtdg4y5r3zarvaryvqyzf3du3", ""],
  ["tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3q0sL5k7", ""],
  ["bc1gmk9yu", ""], ["tb1qqqqqp399et2xygdj5xreqhjjvcmzhxw4aywxecjdzew6hylgvsesrxh6hy", ""],
];
for (const [addr] of bad) {
