const { spawn } = require("child_process");
const B = require("/tmp/b32.js");
const EXE = "/workspace/dataset/test5_executable";
const CONC = 24;
const anomalies = [];
let done = 0, succ = 0;

function run(argv) {
  return new Promise((res) => {
    const p = spawn(EXE, argv, { stdio: ["ignore", "pipe", "pipe"] });
    let so = "", se = "";
    p.stdout.on("data", d => { if (so.length < 100000) so += d; });
    p.stderr.on("data", d => { if (se.length < 100000) se += d; });
    p.on("error", e => res({ rc: "ERR", so: "", se: String(e.message), sig: null }));
    p.on("close", (code, sig) => res({ rc: code, so, se, sig }));
  });
}
function classify(argv, r) {
  const o = r.so.replace(/\n$/, "");
  if (r.rc === 0 && r.se === "" && !r.sig && (o === "(None, None)" || /^\(\d+, \[(\d+(, \d+)*)?\]\)$/.test(o))) {
    if (o !== "(None, None)") succ++;
    return true;
  }
  anomalies.push({ argv: argv.map(s => s.length > 200 ? s.slice(0, 200) + "...(" + s.length + ")" : s), rc: r.rc, sig: r.sig, so: r.so.slice(0, 300), se: r.se.slice(0, 500) });
  return false;
}
// ---------- generators ----------
const CH = B.CHARSET;
const PRINT = []; for (let c = 32; c <= 127; c++) PRINT.push(String.fromCharCode(c));
const WEIRD = ["\x01", "\x07", "\x08", "\t", "\n", "\v", "\f", "\r", "\x1b", "\x7f", "é", "ÿ", "中", "😀", "​", "﻿", "İ", "K", "ſ", "ı", "１", " "];
const ALL = PRINT.concat(WEIRD);
function ri(n) { return Math.floor(Math.random() * n); }
function pick(a) { return a[ri(a.length)]; }
function randStr(len, pool) { let s = ""; for (let i = 0; i < len; i++) s += pick(pool); return s; }

const cases = [];
// 1. pure random junk in both
for (let i = 0; i < 500; i++) cases.push(["--a=" + randStr(ri(12), ALL), "--b=" + randStr(ri(120), ALL)]);
// 2. random bech32-shaped
for (let i = 0; i < 500; i++) {
  const hlen = 1 + ri(90);
  const hrp = randStr(hlen, "abcdefghijklmnopqrstuvwxyz0123456789!~1".split(""));
  const dlen = ri(80);
  const addr = hrp + "1" + randStr(dlen, CH.split(""));
  cases.push(["--a=" + (Math.random() < 0.7 ? hrp : randStr(ri(6), "abc1".split(""))), "--b=" + addr]);
}
// 3. valid-checksum random data parts of every length 0..80
for (let n = 0; n <= 80; n++) {
  for (let k = 0; k < 4; k++) {
    const hrp = randStr(1 + ri(6), "abcxyz1!~".split(""));
    const d = []; for (let i = 0; i < n; i++) d.push(ri(32));
    cases.push(["--a=" + hrp, "--b=" + B.bech32Encode(hrp, d)]);
  }
}
// 4. valid segwit with random ver/prog, then mutate one char (checksum break) or not
for (let i = 0; i < 400; i++) {
  const ver = ri(34);
  const plen = ri(45);
  const prog = []; for (let j = 0; j < plen; j++) prog.push(ri(256));
  const hrp = randStr(1 + ri(85), "abcdefghij0123456789".split(""));
  let addr = B.segwitEncode(hrp, ver, prog);
  if (Math.random() < 0.4) {
    const i2 = ri(addr.length);
    addr = addr.slice(0, i2) + pick(ALL) + addr.slice(i2 + 1);
  }
  if (Math.random() < 0.2) addr = addr.toUpperCase();
  cases.push(["--a=" + hrp, "--b=" + addr]);
}
// 5. long / degenerate
for (const n of [1, 2, 6, 7, 8, 89, 90, 91, 155, 156, 500, 5000, 50000, 200000]) {
  cases.push(["--a=bc", "--b=" + "1".repeat(n)]);
  cases.push(["--a=bc", "--b=" + "q".repeat(n)]);
  cases.push(["--a=" + "1".repeat(n), "--b=" + "1".repeat(n)]);
  cases.push(["--a=bc", "--b=bc1" + "q".repeat(n)]);
  cases.push(["--a=" + "q".repeat(n), "--b=" + "q".repeat(n) + "1" + "q".repeat(6)]);
}
// 6. argv shapes
cases.push(["--a", "bc", "--b", "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4"]);

(async () => {
  let idx = 0;
  async function worker() {
    while (idx < cases.length) {
      const my = cases[idx++];
      const r = await run(my);
      classify(my, r);
      done++;
    }
  }
  await Promise.all(Array.from({ length: CONC }, worker));
  console.log("FUZZ done:", done, "successes:", succ, "anomalies:", anomalies.length);
  console.log(JSON.stringify(anomalies.slice(0, 25), null, 1));
})();

