cd /tmp && node -e '
const {spawnSync}=require("child_process");const B=require("/tmp/b32.js");
const E="/workspace/dataset/test5_executable";
const p20=Array.from({length:20},(_,i)=>i), p40=Array.from({length:40},(_,i)=>i);
let n=0;
for(const ch of ["a","z","0","9","!","~","1","_","x"]){
  for(const hl of [1,83,84]){
    for(const [nm,v,pr] of [["v0/20",0,p20],["v1/40",1,p40],["v1/2",1,[3,10]]]){
      const hrp=ch.repeat(hl); const addr=B.segwitEncode(hrp,v,pr);
      const r=spawnSync(E,["--a="+hrp,"--b="+addr],{encoding:"utf8"}); n++;
      const ok=/^\(\d+,/.test(r.stdout);
      console.log(`ch=${JSON.stringify(ch)} hrplen=${hl} ${nm} addrlen=${addr.length} rc=${r.status} ${ok?"DECODED":"none"} ${r.stderr?"ERR:"+r.stderr:""}`);
    }
  }
}
console.log("probes",n);
' 2>&1

